package com.anaiv.fluxogestao.repository;
import com.anaiv.fluxogestao.entity.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface OrdemServicoPortoRepository extends JpaRepository<OrdemServicoPorto,Long>{Optional<OrdemServicoPorto> findByNumero(String numero);List<OrdemServicoPorto> findByNumeroIn(Collection<String> numeros);List<OrdemServicoPorto> findByOrdemPagamento(OrdemPagamentoPorto op);List<OrdemServicoPorto> findByImportacao(Importacao importacao);List<OrdemServicoPorto> findByMotorista(Motorista motorista);@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao")List<OrdemServicoPorto> findAllParaListagem();@Query("select os.ordemPagamento.id, count(os), coalesce(sum(os.valorTotal),0) from OrdemServicoPorto os where os.ordemPagamento is not null group by os.ordemPagamento.id")List<Object[]> resumirPorOrdemPagamento();@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao where os.dataAtendimento between :inicio and :fim")List<OrdemServicoPorto> findParaListagemPorAtendimento(@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao where os.dataEfetivaPagamento between :inicio and :fim")List<OrdemServicoPorto> findParaListagemPorPagamento(@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);long countByDataAtendimentoBetween(LocalDate inicio,LocalDate fim);@Query("select max(os.dataAtendimento) from OrdemServicoPorto os")LocalDate maiorDataAtendimento();}
